using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using UnityEngine.Networking;
using CatCafePreview.Standalone;
namespace CatCafePreview
{
 public sealed class StandaloneGrowthBatchSmoke:MonoBehaviour
 {
  static int checks;string output;LocalCafeBackend backend;bool failed;
  static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
  public static CafeRules Rules(){var r=StandaloneEncounterConversationSmoke.Rules();r.growth.threshold=1;r.growth.service_xp=1;r.growth.rest_xp=1;r.intake.day=9999;r.regular_introduction.day=9999;return r;}
  public static CafeResponse Send(LocalCafeBackend b,string kind,string cat=null,string choice=null,int slot=1,string[] working=null){var s=b.Simulation.State;return StandaloneDispatchConversationSmoke.Raw(b,JsonUtility.ToJson(new PythonShiftCommand{kind=kind,cat_id=cat,choice=choice,save_id=slot.ToString(),save_slot=slot,request_id=Guid.NewGuid().ToString("N"),instance_id=s.instance_id,expected_revision=s.revision,working_cats=working??new string[0],autoplay_objective="popularity",autoplay_mode="clear",autoplay_days=3}));}
  static void Good(LocalCafeBackend b,string kind,string cat=null,string choice=null,int slot=1,string[] working=null){var r=Send(b,kind,cat,choice,slot,working);Check(r.result==UnityWebRequest.Result.Success,kind+": "+r.error);}
  static void Drain(LocalCafeBackend b){int n=0;while(b.Simulation.GrowthWaiting && n++<20){Good(b,"resolve_growth_auto");Good(b,"resolve_growth_batch");}Check(!b.Simulation.GrowthWaiting,"Unresolved growth");}
  static void Close(LocalCafeBackend b){int n=0;while(b.Simulation.State.phase=="open" && n++<200){if(b.Simulation.State.tick==b.Simulation.Rules.opening_ticks-1){Good(b,"save_game",slot:10);Good(b,"load_game",slot:10);Check(b.Simulation.State.phase=="open" && !b.Simulation.GrowthWaiting,"Before-close restore blocked service");}Good(b,"advance_business");}Check(b.Simulation.State.phase=="closed","Closing failed");}
  public static int BackendCases(string path)
  {
   checks=0;Directory.CreateDirectory(path);var b=new LocalCafeBackend(Path.Combine(path,"main"),Rules());Good(b,"new_game",choice:"free");Good(b,"set_shifts",working:b.Simulation.State.cats.Take(2).Select(c=>c.id).ToArray());Good(b,"start_business");
   int n=0;while(!b.Simulation.State.growth.Any(g=>b.Simulation.GrowthPendingKind(g)!=null) && n++<100)Good(b,"advance_business");
   Check(b.Simulation.State.phase=="open" && !b.Simulation.GrowthWaiting && b.View().growth_choices.Length==0,"Growth interrupted service");
   Check(Send(b,"resolve_growth_auto").result!=UnityWebRequest.Result.Success,"Early auto selection allowed");Good(b,"save_game",slot:2);b=new LocalCafeBackend(Path.Combine(path,"main"),Rules());Good(b,"load_game",slot:2);Check(!b.Simulation.GrowthWaiting && b.Simulation.State.growth.Any(g=>b.Simulation.GrowthPendingKind(g)!=null),"Open pending save lost");Close(b);
   Check(b.View().growth_choices.Length>1,"Multiple cats missing");Good(b,"save_game",slot:3);
   Check(Send(b,"next_day").result!=UnityWebRequest.Result.Success,"Skipped pending growth");string history=JsonUtility.ToJson(new History{rows=b.Simulation.State.history.ToArray(),visits=b.Simulation.State.visits.ToArray()});double revenue=b.Simulation.State.revenue,funds=b.Simulation.State.funds;
   Good(b,"resolve_growth_auto");var recommended=JsonUtility.ToJson(new Selections{rows=b.Simulation.State.growth_selections.ToArray()});Good(b,"resolve_growth_auto");Check(recommended==JsonUtility.ToJson(new Selections{rows=b.Simulation.State.growth_selections.ToArray()}),"Auto was not deterministic");Check(b.Simulation.State.growth.All(g=>g.specialization==null),"Preview applied effects");
   var row=b.View().growth_choices[0];Good(b,"resolve_growth_stage",row.cat_id,"rest");Good(b,"resolve_growth_auto");Check(b.View().growth_choices[0].selected=="rest","Auto overwrote manual choice");Good(b,"save_game",slot:4);b=new LocalCafeBackend(Path.Combine(path,"main"),Rules());Good(b,"load_game",slot:4);Check(b.View().growth_choices[0].selected=="rest","Manual staging lost on restart");
   Good(b,"resolve_growth_batch");Check(b.Simulation.GrowthCat(row.cat_id).specialization=="rest","Manual override lost");Check(b.Simulation.State.revenue==revenue && b.Simulation.State.funds==funds && history==JsonUtility.ToJson(new History{rows=b.Simulation.State.history.ToArray(),visits=b.Simulation.State.visits.ToArray()}),"Retroactive accounting");int firstCount=b.Simulation.State.growth_operations.Count;Check(Send(b,"resolve_growth_batch").result!=UnityWebRequest.Result.Success && b.Simulation.State.growth_operations.Count==firstCount,"Duplicate batch applied next stage");Drain(b);int count=b.Simulation.State.growth_operations.Count;Check(Send(b,"resolve_growth_batch").result!=UnityWebRequest.Result.Success && b.Simulation.State.growth_operations.Count==count,"Duplicate confirmation applied");Good(b,"save_game",slot:5);Good(b,"next_day");
   // Legacy-style saves have no staging field; actual pending experience remains authoritative.
   Good(b,"load_game",slot:3);b.Simulation.State.growth_selections=null;Good(b,"save_game",slot:6);Good(b,"load_game",slot:6);Check(b.Simulation.GrowthWaiting,"Legacy pending vanished");Drain(b);Good(b,"next_day");
   var dayoff=new LocalCafeBackend(Path.Combine(path,"dayoff"),Rules());Good(dayoff,"new_game",choice:"free");Good(dayoff,"day_off");Check(dayoff.Simulation.GrowthWaiting && dayoff.Simulation.State.phase=="closed","Day off timing");Drain(dayoff);Good(dayoff,"next_day");
   // Pure recommendation covers constrained stages and all preference ties.
   var sim=b.Simulation;var cat=sim.State.growth[0];var d=sim.Definition(cat.cat_id);d.type_preferences=Enumerable.Repeat(1.0,8).ToArray();d.intensity_preferences=new[]{1.0,1.0,1.0};
   var fixture=new CafeGrowth{cat_id=cat.cat_id,specialization="service",mastery_groups=new[]{100,100,100}};
   Check(sim.RecommendGrowth(fixture).choice=="play","Group tie order");fixture.mastery="play";fixture.type_mastery_actions=new[]{100,100,100,100,0,0,0,0};fixture.second_mastery_groups=new[]{0,100,100};Check(sim.RecommendGrowth(fixture).choice=="contact","Learned group selected");fixture.second_mastery="contact";Check(sim.RecommendGrowth(fixture).choice=="teaser","Type tie order");fixture.type_mastery="teaser";fixture.second_type_mastery_actions=new[]{0,100,100,100,0,0,0,0};Check(sim.RecommendGrowth(fixture).choice=="ball","Already learned type selected");
   var auto=new LocalCafeBackend(Path.Combine(path,"auto"),Rules());Good(auto,"new_game",choice:"popularity");Good(auto,"start_autoplay");n=0;while(auto.Simulation.State.autoplay.running && n++<100){Good(auto,"step_autoplay");if(auto.Simulation.State.growth_operations.Any(o=>o.decision_reason!=null))break;}Check(auto.Simulation.State.growth_operations.Any(o=>!string.IsNullOrEmpty(o.decision_reason)),"Autoplay did not use shared selection");Good(auto,"save_game");Good(auto,"load_game");if(auto.Simulation.State.autoplay.running){Drain(auto);Good(auto,"resume_autoplay");Good(auto,"pause_autoplay");Good(auto,"stop_autoplay");}

   var dr=Rules();dr.growth.dispatch_xp=1;dr.growth.rest_xp=0;var dispatch=new LocalCafeBackend(Path.Combine(path,"dispatch"),dr);Good(dispatch,"new_game",choice:"free");string dispatched=dispatch.Simulation.State.cats[0].id;Good(dispatch,"dispatch_general",dispatched,dr.dispatch.id);Good(dispatch,"day_off");Drain(dispatch);if(dispatch.Simulation.State.phase=="closed")Good(dispatch,"next_day");var entry=dispatch.Simulation.State.dispatches.Single();dispatch.Simulation.Execute("resolve_activity",choice:"receive",source:entry.id);Check(dispatch.Simulation.State.phase=="preparation" && dispatch.Simulation.GrowthWaiting,"Preparation return growth timing");Good(dispatch,"save_game",slot:7);Good(dispatch,"load_game",slot:7);Drain(dispatch);Good(dispatch,"set_shifts",working:dispatch.Simulation.State.cats.Take(2).Select(c=>c.id).ToArray());Good(dispatch,"start_business");
   var er=Rules();er.opening_ticks=8;er.arrival_ticks=new[]{0};er.patterns=new[]{new WeekPattern{days=Enumerable.Range(0,7).ToArray()}};er.goal_stages=new[]{new GoalStageRule{days=20,target=1}};er.growth.service_xp=0;var ending=new LocalCafeBackend(Path.Combine(path,"ending"),er);Good(ending,"new_game",choice:"popularity");Good(ending,"set_shifts",working:ending.Simulation.State.cats.Take(1).Select(c=>c.id).ToArray());Good(ending,"start_business");Close(ending);Check(ending.Simulation.GrowthWaiting && ending.PopularityEndingPending,"Ending overlap absent");Good(ending,"save_game",slot:8);Good(ending,"load_game",slot:8);Drain(ending);var ep=ending.PopularityEnding.progress;ep.node=CafePopularityEnding.Lines(CafePopularityEnding.Record(ending.Simulation.State),"猫").Length;CafePopularityEnding.Finish(ep);Good(ending,"continue_goal");Good(ending,"next_day");Check(ending.Simulation.State.phase=="preparation","Ending growth deadlock");
   var ae=new LocalCafeBackend(Path.Combine(path,"auto-ending"),er);Good(ae,"new_game",choice:"popularity");Good(ae,"start_autoplay");n=0;while(ae.Simulation.State.autoplay.running && n++<100)Good(ae,"step_autoplay");Check(!ae.Simulation.GrowthWaiting && ae.PopularityEndingPending && !ae.Simulation.State.autoplay.running,"Autoplay ending growth deadlock");Good(ae,"save_game",slot:9);Good(ae,"load_game",slot:9);
   File.WriteAllText(Path.Combine(path,"backend-result.txt"),"PASS "+checks);return checks;
  }
  [Serializable]class History{public CafeDayResult[] rows;public CafeVisit[] visits;}
  [Serializable]class Selections{public CafeGrowthSelection[] rows;}
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-growth-batch-check");if(i<0)return;var q=new GameObject("Growth batch verification").AddComponent<StandaloneGrowthBatchSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;Application.logMessageReceived+=q.Log;try{BackendCases(Path.Combine(q.output,"cases"));q.backend=new LocalCafeBackend(Path.Combine(q.output,"visible"),Rules());Good(q.backend,"new_game",choice:"free");Good(q.backend,"set_shifts",working:q.backend.Simulation.State.cats.Take(2).Select(c=>c.id).ToArray());Good(q.backend,"start_business");q.StartCoroutine(q.Guard());}catch(Exception e){q.Fail(e);}}
  void Fail(Exception e){if(failed)return;failed=true;File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(1);}
  void Log(string m,string s,LogType t){if(t==LogType.Error || t==LogType.Exception || t==LogType.Assert)Fail(new Exception(m+"\n"+s));}
  void OnDestroy(){Application.logMessageReceived-=Log;}
  IEnumerator Guard(){var r=Run();while(true){bool more;try{more=r.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return r.Current;}}
  IEnumerator Run(){Screen.SetResolution(1280,800,false);CafeBackends.UseLocal(backend);SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var client=FindObjectOfType<PythonStateClient>();var panel=client.GetComponent<PythonGrowthPanel>();int n=0;while(!backend.Simulation.State.growth.Any(g=>backend.Simulation.GrowthPendingKind(g)!=null) && n++<100)Good(backend,"advance_business");Apply(client);yield return null;Check(!panel.panel.activeSelf,"Open growth modal visible");ScreenCapture.CaptureScreenshot(Path.Combine(output,"BusinessUninterrupted.png"));yield return new WaitForEndOfFrame();Close(backend);Apply(client);yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"GrowthReview.png"));yield return new WaitForEndOfFrame();File.WriteAllText(Path.Combine(output,"ready.txt"),"Use visible growth controls: manual choice, automatic decision, batch confirm.");
   if(Environment.GetCommandLineArgs().Contains("--growth-manual")){while(backend.Simulation.GrowthWaiting)yield return null;while(!client.CanSendCommands)yield return null;}else{Good(backend,"resolve_growth_auto");Apply(client);yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"GrowthRecommendation.png"));yield return new WaitForEndOfFrame();Drain(backend);}
   Good(backend,"next_day");Apply(client);yield return null;Check(backend.Simulation.State.phase=="preparation" && !panel.panel.activeSelf,"Next day failed");ScreenCapture.CaptureScreenshot(Path.Combine(output,"NextDay.png"));yield return new WaitForEndOfFrame();File.WriteAllText(Path.Combine(output,"result.txt"),"PASS "+checks+" checks; service, growth review, next day visible");if(!Environment.GetCommandLineArgs().Contains("--growth-manual"))Application.Quit(0);
  }
  void Apply(PythonStateClient c){typeof(PythonStateClient).GetMethod("Accept",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(c,new object[]{JsonUtility.FromJson<PythonCafeState>(JsonUtility.ToJson(backend.View()))});Canvas.ForceUpdateCanvases();}
 }
